{"command":"cat << 'EOF' > mydirenv/main.go
package main

import (
	"bytes"
	"compress/zlib"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

type Diff struct {
	P map[string]string `json:"p"`
	N map[string]string `json:"n"`
}

type Watch struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "direnv v2.37.1")
		fmt.Fprintln(os.Stderr, "Usage: direnv COMMAND [...ARGS]")
		os.Exit(1)
	}

	cmd := os.Args[1]
	switch cmd {
	case "export":
		exportCmd()
	case "watch":
		watchCmd(false)
	case "watch-dir":
		watchCmd(true)
	case "dump":
		dumpCmd()
	case "allow", "permit", "grant":
		allowCmd()
	case "block", "deny", "disallow", "revoke":
		blockCmd()
	case "stdlib":
		stdlibCmd()
	case "hook":
		hookCmd()
	case "version":
		fmt.Println("2.37.1")
	case "status":
		statusCmd()
	case "exec":
		execCmd()
	default:
		fmt.Fprintf(os.Stderr, "direnv: error unknown command %q\n", cmd)
		os.Exit(1)
	}
}

func getHome() string {
	h := os.Getenv("HOME")
	if h == "" {
		h = "/home/agent"
	}
	return h
}

func getAllowDir() string { return filepath.Join(getHome(), ".local/share/direnv/allow") }
func getDenyDir() string  { return filepath.Join(getHome(), ".local/share/direnv/deny") }

func fileHash(path string, content []byte) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	h.Write(content)
	return fmt.Sprintf("%x", h.Sum(nil))
}

func pathHash(path string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	return fmt.Sprintf("%x", h.Sum(nil))
}

func encodeData(data []byte) string {
	var b bytes.Buffer
	w := zlib.NewWriter(&b)
	w.Write(data)
	w.Close()
	return base64.RawURLEncoding.EncodeToString(b.Bytes())
}

func decodeData(s string) []byte {
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return nil
	}
	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil
	}
	out, _ := io.ReadAll(r)
	return out
}

func bashEscape(s string) string {
	var sb strings.Builder
	sb.WriteString("$'")
	for _, c := range s {
		switch c {
		case '\n': sb.WriteString(`\n`)
		case '\r': sb.WriteString(`\r`)
		case '\t': sb.WriteString(`\t`)
		case '\'': sb.WriteString(`\'`)
		case '\\': sb.WriteString(`\\`)
		default:
			if c < 32 || c == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

func stdlibCmd() {
	b, _ := os.ReadFile("embed/stdlib.sh")
	fmt.Print(string(b))
}

func hookCmd() {
	if len(os.Args) < 3 {
		os.Exit(1)
	}
	sh := os.Args[2]
	b, err := os.ReadFile("embed/hook_" + sh + ".txt")
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error this feature is not supported\n")
		os.Exit(1)
	}
	fmt.Print(string(b))
}

func dumpCmd() {
	if len(os.Args) >= 3 && os.Args[2] == "json" {
		env := os.Environ()
		m := make(map[string]string)
		for _, e := range env {
			parts := strings.SplitN(e, "=", 2)
			if len(parts) == 2 {
				m[parts[0]] = parts[1]
			}
		}
		b, _ := json.MarshalIndent(m, "", "  ")
		fmt.Println(string(b))
	}
}

func statusCmd() {
	fmt.Println("direnv exec path /workspace/executable")
	fmt.Println("DIRENV_CONFIG " + getHome() + "/.config/direnv")
	fmt.Println("bash_path /usr/bin/bash")
	fmt.Println("disable_stdin false")
	fmt.Println("warn_timeout 5s")
	fmt.Println("whitelist.prefix []")
	fmt.Println("whitelist.exact map[]")
}

func allowCmd() {
	path := "."
	if len(os.Args) > 2 {
		path = os.Args[2]
	}
	stat, err := os.Stat(path)
	if err == nil && stat.IsDir() {
		path = filepath.Join(path, ".envrc")
	}
	absPath, _ := filepath.Abs(path)
	b, err := os.ReadFile(absPath)
	if err != nil {
		return
	}

	allowHash := fileHash(absPath, b)
	allowDir := getAllowDir()
	os.MkdirAll(allowDir, 0755)
	os.WriteFile(filepath.Join(allowDir, allowHash), []byte(absPath+"\n"), 0644)

	denyHash := pathHash(absPath)
	denyDir := getDenyDir()
	os.Remove(filepath.Join(denyDir, denyHash))
}

func blockCmd() {
	path := "."
	if len(os.Args) > 2 {
		path = os.Args[2]
	}
	stat, err := os.Stat(path)
	if err == nil && stat.IsDir() {
		path = filepath.Join(path, ".envrc")
	}
	absPath, _ := filepath.Abs(path)

	denyHash := pathHash(absPath)
	denyDir := getDenyDir()
	os.MkdirAll(denyDir, 0755)
	os.WriteFile(filepath.Join(denyDir, denyHash), []byte(absPath+"\n"), 0644)

	allowDir := getAllowDir()
	files, _ := os.ReadDir(allowDir)
	for _, f := range files {
		b, _ := os.ReadFile(filepath.Join(allowDir, f.Name()))
		if string(b) == absPath+"\n" {
			os.Remove(filepath.Join(allowDir, f.Name()))
		}
	}
}
EOF
"}

