{"command":"cat << 'EOF' >> mydirenv/main.go
func exportCmd() {
	if len(os.Args) < 3 {
		return
	}
	targetShell := os.Args[2]

	pwd, _ := os.Getwd()
	rcPath := ""
	for dir := pwd; ; {
		p := filepath.Join(dir, ".envrc")
		if _, err := os.Stat(p); err == nil {
			rcPath = p
			break
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	prevDiffStr := os.Getenv("DIRENV_DIFF")
	prevDiff := Diff{P: make(map[string]string), N: make(map[string]string)}
	if prevDiffStr != "" {
		json.Unmarshal(decodeData(prevDiffStr), &prevDiff)
	}
	if prevDiff.P == nil { prevDiff.P = make(map[string]string) }
	if prevDiff.N == nil { prevDiff.N = make(map[string]string) }

	// Revert to baseline
	baseline := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			baseline[parts[0]] = parts[1]
		}
	}

	for k := range prevDiff.N {
		delete(baseline, k)
	}
	for k, v := range prevDiff.P {
		baseline[k] = v
	}
	delete(baseline, "DIRENV_DIFF")
	delete(baseline, "DIRENV_WATCHES")
	delete(baseline, "DIRENV_DIR")
	delete(baseline, "DIRENV_FILE")

	if rcPath == "" {
		// Output reverts
		if targetShell == "json" {
			fmt.Println("{}")
			return
		}
		for k := range prevDiff.N {
			if v, ok := prevDiff.P[k]; ok {
				fmt.Printf("export %s=%s;", k, bashEscape(v))
			} else {
				fmt.Printf("unset %s;", k)
			}
		}
		fmt.Print("unset DIRENV_DIFF;unset DIRENV_WATCHES;unset DIRENV_DIR;unset DIRENV_FILE;")
		return
	}

	rcDir := filepath.Dir(rcPath)
	direnvDir := "-" + rcDir

	// Check watches
	watchesStr := os.Getenv("DIRENV_WATCHES")
	watches := []Watch{}
	if watchesStr != "" {
		json.Unmarshal(decodeData(watchesStr), &watches)
	}

	watchesMatch := true
	if len(watches) == 0 {
		watchesMatch = false
	} else {
		for _, w := range watches {
			stat, err := os.Stat(w.Path)
			exists := err == nil
			if exists != w.Exists {
				watchesMatch = false
				break
			}
			if exists && stat.ModTime().Unix() != w.ModTime {
				watchesMatch = false
				break
			}
		}
	}

	if watchesMatch && os.Getenv("DIRENV_DIR") == direnvDir {
		return
	}

	// We need to re-evaluate
	rcContent, _ := os.ReadFile(rcPath)
	allowHash := fileHash(rcPath, rcContent)
	allowPath := filepath.Join(getAllowDir(), allowHash)
	denyHash := pathHash(rcPath)
	denyPath := filepath.Join(getDenyDir(), denyHash)

	allowed := false
	if _, err := os.Stat(allowPath); err == nil {
		allowed = true
	}

	// Revert first if not allowed or whatever
	if !allowed {
		fmt.Fprintf(os.Stderr, "direnv: error %s is blocked. Run `direnv allow` to approve its content\n", rcPath)
		if targetShell == "json" {
			b, _ := json.Marshal(map[string]string{
				"DIRENV_DIR": direnvDir,
				"DIRENV_FILE": rcPath,
			})
			fmt.Println(string(b))
			return
		}
		// Unset old stuff and export just DIRENV_DIR and DIRENV_FILE
		for k := range prevDiff.N {
			if v, ok := prevDiff.P[k]; ok {
				fmt.Printf("export %s=%s;", k, bashEscape(v))
			} else {
				if !strings.HasPrefix(k, "DIRENV_") {
					fmt.Printf("unset %s;", k)
				}
			}
		}
		fmt.Printf("export DIRENV_DIR=%s;export DIRENV_FILE=%s;", bashEscape(direnvDir), bashEscape(rcPath))

		// generate new watches? direnv does export watches even if blocked!
		newWatches := []Watch{
			{Path: rcPath, ModTime: fileModTime(rcPath), Exists: true},
			{Path: allowPath, ModTime: fileModTime(allowPath), Exists: fileExists(allowPath)},
			{Path: denyPath, ModTime: fileModTime(denyPath), Exists: fileExists(denyPath)},
		}
		newWatchesStr := encodeData(mustMarshal(newWatches))
		fmt.Printf("export DIRENV_WATCHES=%s;", bashEscape(newWatchesStr))
		return
	}

	fmt.Fprintf(os.Stderr, "direnv: loading %s\n", rcPath)

	// Generate initial watches
	newWatches := []Watch{
		{Path: rcPath, ModTime: fileModTime(rcPath), Exists: true},
		{Path: allowPath, ModTime: fileModTime(allowPath), Exists: fileExists(allowPath)},
		{Path: denyPath, ModTime: fileModTime(denyPath), Exists: fileExists(denyPath)},
	}
	newWatchesStr := encodeData(mustMarshal(newWatches))

	// Run bash
	cmd := exec.Command("bash", "-c", `eval "$(cat embed/stdlib.sh)" && direnv_load "`+rcPath+`" && ./executable dump json ""`)
	cmd.Dir = pwd
	cmdEnv := []string{}
	for k, v := range baseline {
		cmdEnv = append(cmdEnv, k+"="+v)
	}
	cmdEnv = append(cmdEnv, "DIRENV_WATCHES="+newWatchesStr)
	cmdEnv = append(cmdEnv, "PATH="+os.Getenv("PATH")) // keep PATH for executable
	cmd.Env = cmdEnv

	out, err := cmd.Output()
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error loading %s: %v\n", rcPath, err)
		return
	}

	newEnv := make(map[string]string)
	json.Unmarshal(out, &newEnv)

	finalWatches := newEnv["DIRENV_WATCHES"]
	if finalWatches == "" {
		finalWatches = newWatchesStr
	}
	delete(newEnv, "DIRENV_WATCHES")
	delete(newEnv, "DIRENV_DIFF")
	delete(newEnv, "DIRENV_DIR")
	delete(newEnv, "DIRENV_FILE")

	newDiff := Diff{P: make(map[string]string), N: make(map[string]string)}
	newDiff.N["DIRENV_DIR"] = direnvDir
	newDiff.N["DIRENV_FILE"] = rcPath
	newDiff.N["DIRENV_WATCHES"] = finalWatches

	for k, v := range newEnv {
		oldV, ok := baseline[k]
		if !ok {
			newDiff.N[k] = v
			fmt.Fprintf(os.Stderr, "direnv: export +%s\n", k)
		} else if oldV != v {
			newDiff.N[k] = v
			newDiff.P[k] = oldV
			fmt.Fprintf(os.Stderr, "direnv: export ~%s\n", k)
		}
	}
	for k, v := range baseline {
		if _, ok := newEnv[k]; !ok {
			newDiff.P[k] = v
			fmt.Fprintf(os.Stderr, "direnv: export -%s\n", k)
		}
	}

	diffStr := encodeData(mustMarshal(newDiff))

	if targetShell == "json" {
		exp := make(map[string]string)
		for k, v := range newDiff.N {
			exp[k] = v
		}
		exp["DIRENV_DIFF"] = diffStr
		b, _ := json.MarshalIndent(exp, "", "  ")
		fmt.Println(string(b))
		return
	}

	// Unset variables that were in prevDiff.N but not in newDiff.N
	for k := range prevDiff.N {
		if _, ok := newDiff.N[k]; !ok {
			if !strings.HasPrefix(k, "DIRENV_") {
				fmt.Printf("unset %s;", k)
			}
		}
	}

	for k, v := range newDiff.N {
		fmt.Printf("export %s=%s;", k, bashEscape(v))
	}
	fmt.Printf("export DIRENV_DIFF=%s;", bashEscape(diffStr))
}

func fileExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func fileModTime(p string) int64 {
	stat, err := os.Stat(p)
	if err == nil {
