func fileHash(path string, content []byte) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	h.Write(content)
	return fmt.Sprintf("%x", h.Sum(nil))
}

func pathHash(path string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	return fmt.Sprintf("%x", h.Sum(nil))
}

func encodeData(data []byte) string {
	var b bytes.Buffer
	w := zlib.NewWriter(&b)
	w.Write(data)
	w.Close()
	return base64.RawURLEncoding.EncodeToString(b.Bytes())
}

func decodeData(s string) []byte {
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return nil
	}
	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil
	}
	out, _ := io.ReadAll(r)
	return out
}

func bashEscape(s string) string {
	var sb strings.Builder
	sb.WriteString("$'")
	for _, c := range s {
		switch c {
		case '\n': sb.WriteString(`\n`)
		case '\r': sb.WriteString(`\r`)
		case '\t': sb.WriteString(`\t`)
		case '\'': sb.WriteString(`\'`)
		case '\\': sb.WriteString(`\\`)
		default:
			if c < 32 || c == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

