type Diff struct {
	P map[string]string `json:"p"`
	N map[string]string `json:"n"`
}

type Watch struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "direnv v2.37.1")
		fmt.Fprintln(os.Stderr, "Usage: direnv COMMAND [...ARGS]")
		os.Exit(1)
	}

	cmd := os.Args[1]
	switch cmd {
	case "export":
		exportCmd()
	case "watch":
		watchCmd(false)
	case "watch-dir":
		watchCmd(true)
	case "dump":
		dumpCmd()
	case "allow", "permit", "grant":
		allowCmd()
	case "block", "deny", "disallow", "revoke":
		blockCmd()
	case "stdlib":
		stdlibCmd()
	case "hook":
		hookCmd()
	case "version":
		fmt.Println("2.37.1")
	case "status":
		statusCmd()
	case "exec":
		execCmd()
	default:
		fmt.Fprintf(os.Stderr, "direnv: error unknown command %q\n", cmd)
		os.Exit(1)
	}
}

func getHome() string {
	h := os.Getenv("HOME")
	if h == "" {
		h = "/home/agent"
	}
	return h
}

func getAllowDir() string { return filepath.Join(getHome(), ".local/share/direnv/allow") }
func getDenyDir() string  { return filepath.Join(getHome(), ".local/share/direnv/deny") }

func fileHash(path string, content []byte) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	h.Write(content)
	return fmt.Sprintf("%x", h.Sum(nil))
}

func pathHash(path string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	return fmt.Sprintf("%x", h.Sum(nil))
}

func encodeData(data []byte) string {
	var b bytes.Buffer
	w := zlib.NewWriter(&b)
	w.Write(data)
	w.Close()
	return base64.RawURLEncoding.EncodeToString(b.Bytes())
}

func decodeData(s string) []byte {
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return nil
	}
	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil
	}
	out, _ := io.ReadAll(r)
	return out
}

func bashEscape(s string) string {
	var sb strings.Builder
	sb.WriteString("$'")
	for _, c := range s {
		switch c {
		case '\n': sb.WriteString(`\n`)
		case '\r': sb.WriteString(`\r`)
		case '\t': sb.WriteString(`\t`)
		case '\'': sb.WriteString(`\'`)
		case '\\': sb.WriteString(`\\`)
		default:
			if c < 32 || c == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				sb.WriteRune(c)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

