		p := filepath.Join(dirIter, ".envrc")
		if _, err := os.Stat(p); err == nil {
			rcPath = p
			break
		}
		parent := filepath.Dir(dirIter)
		if parent == dirIter {
			break
		}
		dirIter = parent
	}

	prevDiffStr := os.Getenv("DIRENV_DIFF")
	prevDiff := Diff{P: make(map[string]string), N: make(map[string]string)}
	if prevDiffStr != "" {
		json.Unmarshal(decodeData(prevDiffStr), &prevDiff)
	}
	if prevDiff.P == nil { prevDiff.P = make(map[string]string) }
	if prevDiff.N == nil { prevDiff.N = make(map[string]string) }

	baseline := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			baseline[parts[0]] = parts[1]
		}
	}

	for k := range prevDiff.N {
		delete(baseline, k)
	}
	for k, v := range prevDiff.P {
		baseline[k] = v
	}
	delete(baseline, "DIRENV_DIFF")
	delete(baseline, "DIRENV_WATCHES")
	delete(baseline, "DIRENV_DIR")
	delete(baseline, "DIRENV_FILE")

	var finalEnv []string

	if rcPath == "" {
		for k, v := range baseline {
			finalEnv = append(finalEnv, k+"="+v)
		}
	} else {
		rcDir := filepath.Dir(rcPath)
		direnvDir := "-" + rcDir

		watchesStr := os.Getenv("DIRENV_WATCHES")
		watches := []Watch{}
		if watchesStr != "" {
			json.Unmarshal(decodeData(watchesStr), &watches)
		}

		watchesMatch := true
		if len(watches) == 0 {
			watchesMatch = false
		} else {
			for _, w := range watches {
				stat, err := os.Stat(w.Path)
				exists := err == nil
				if exists != w.Exists {
					watchesMatch = false
					break
				}
				if exists && stat.ModTime().Unix() != w.ModTime {
					watchesMatch = false
					break
				}
			}
		}

		if watchesMatch && os.Getenv("DIRENV_DIR") == direnvDir {
			for _, e := range os.Environ() {
				finalEnv = append(finalEnv, e)
			}
		} else {
			rcContent, _ := os.ReadFile(rcPath)
			allowHash := fileHash(rcPath, rcContent)
			allowPath := filepath.Join(getAllowDir(), allowHash)
			denyHash := pathHash(rcPath)
			denyPath := filepath.Join(getDenyDir(), denyHash)

			allowed := false
			if _, err := os.Stat(allowPath); err == nil {
				allowed = true
			}

			if !allowed {
				fmt.Fprintf(os.Stderr, "direnv: error %s is blocked. Run `direnv allow` to approve its content\n", rcPath)
				os.Exit(1)
			}

			newWatches := []Watch{
				{Path: rcPath, ModTime: fileModTime(rcPath), Exists: true},
				{Path: allowPath, ModTime: fileModTime(allowPath), Exists: fileExists(allowPath)},
				{Path: denyPath, ModTime: fileModTime(denyPath), Exists: fileExists(denyPath)},
			}
			newWatchesStr := encodeData(mustMarshal(newWatches))

			out, err := doExportCmdBash(rcPath, baseline, newWatchesStr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "direnv: error loading %s: %v\n", rcPath, err)
				os.Exit(1)
			}

			newEnv := make(map[string]string)
			json.Unmarshal(out, &newEnv)

			finalWatches := newEnv["DIRENV_WATCHES"]
			if finalWatches == "" {
				finalWatches = newWatchesStr
			}
			delete(newEnv, "DIRENV_WATCHES")
			delete(newEnv, "DIRENV_DIFF")
			delete(newEnv, "DIRENV_DIR")
			delete(newEnv, "DIRENV_FILE")

			newDiff := Diff{P: make(map[string]string), N: make(map[string]string)}
			newDiff.N["DIRENV_DIR"] = direnvDir
			newDiff.N["DIRENV_FILE"] = rcPath
			newDiff.N["DIRENV_WATCHES"] = finalWatches

			for k, v := range newEnv {
				if isIgnoredVar(k) { continue }
				oldV, ok := baseline[k]
				if !ok {
					newDiff.N[k] = v
				} else if oldV != v {
					newDiff.N[k] = v
					newDiff.P[k] = oldV
				}
			}
			for k, v := range baseline {
				if isIgnoredVar(k) { continue }
				if _, ok := newEnv[k]; !ok {
					newDiff.P[k] = v
				}
			}

			for k, v := range baseline {
				if _, ok := newEnv[k]; !ok {
					// it was deleted
				} else {
				    // if it wasn't deleted, use the new value
				    finalEnv = append(finalEnv, k+"="+newEnv[k])
				}
			}
			// add newly added variables
			for k, v := range newEnv {
				if _, ok := baseline[k]; !ok {
					finalEnv = append(finalEnv, k+"="+v)
				}
			}

			finalEnv = append(finalEnv, "DIRENV_DIFF="+encodeData(mustMarshal(newDiff)))
			finalEnv = append(finalEnv, "DIRENV_DIR="+direnvDir)
			finalEnv = append(finalEnv, "DIRENV_FILE="+rcPath)
			finalEnv = append(finalEnv, "DIRENV_WATCHES="+finalWatches)
		}
	}

	bin, err := exec.LookPath(cmdName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "direnv: error %v\n", err)
		os.Exit(1)
	}
	os.Chdir(pwd) // restore wd if getRC changed it? No, getRC didn't change it.
	syscall.Exec(bin, cmdArgs, finalEnv)
}

func fileExists(p string) bool {
	_, err := os.Stat(p)
	return err == nil
}

func fileModTime(p string) int64 {
	stat, err := os.Stat(p)
	if err == nil {
		return stat.ModTime().Unix()
	}
	return 0
}

func mustMarshal(v interface{}) []byte {
	b, _ := json.Marshal(v)
	return b
}
EOF
/workspace/compile.sh"}

