type Diff struct {
	P map[string]string `json:"p"`
	N map[string]string `json:"n"`
}

type Watch struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

func main() {
