	if err == nil && stat.IsDir() {
		path = filepath.Join(path, ".envrc")
	}
	absPath, _ := filepath.Abs(path)
	b, err := os.ReadFile(absPath)
	if err != nil {
		return
	}

	allowHash := fileHash(absPath, b)
	allowDir := getAllowDir()
	os.MkdirAll(allowDir, 0755)
	os.WriteFile(filepath.Join(allowDir, allowHash), []byte(absPath+"\n"), 0644)

	denyHash := pathHash(absPath)
	denyDir := getDenyDir()
	os.Remove(filepath.Join(denyDir, denyHash))
}

func blockCmd() {
