	return encodeData(b)
}

func watchCmd(dirMode bool) {
	if len(os.Args) < 4 {
		return
	}
	wStr := os.Getenv("DIRENV_WATCHES")
	w := getWatches(wStr)

	for i := 3; i < len(os.Args); i++ {
		path, _ := filepath.Abs(os.Args[i])
		if dirMode {
			filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
				var mtime int64 = 0
				exists := false
				if err == nil {
					mtime = info.ModTime().Unix()
					exists = true
				}
				w = append(w, Watch{Path: p, ModTime: mtime, Exists: exists})
				return nil
			})
		} else {
			var mtime int64 = 0
			exists := false
			if info, err := os.Stat(path); err == nil {
				mtime = info.ModTime().Unix()
				exists = true
			}
			w = append(w, Watch{Path: path, ModTime: mtime, Exists: exists})
		}
	}

	fmt.Printf("export DIRENV_WATCHES=%s;", bashEscape(encodeWatches(w)))
