func bashEscape(s string) string {
	var sb strings.Builder
	sb.WriteString("$'")
	for _, c := range s {
		switch c {
		case '\n': sb.WriteString(`\n`)
		case '\r': sb.WriteString(`\r`)
		case '\t': sb.WriteString(`\t`)
		case '\'': sb.WriteString(`\'`)
		case '\\': sb.WriteString(`\\`)
		default:
			if c < 32 || c == 127 {
				sb.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				sb.WriteRune(c)
			}
		}
